cypress_script:
describe('API Response Handling on Links Page', () => {
  it('should navigate to the Home page successfully when clicking on the Home link', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('#simpleLink').click();
    cy.url().should('eq', 'https://demoqa.com/');
  });
  it('should not change the URL when clicking on the Bad Request link', () => {
    cy.visit('https://demoqa.com/links');
    cy.get('#bad-request').click();
    cy.url().should('eq', 'https://demoqa.com/links');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

 test.describe('API Response Handling on Links Page', () => {
   test('should navigate to the Home page successfully when clicking on the Home link', async ({ page }) => {
     await page.goto('https://demoqa.com/links');
     await page.click('#simpleLink');
     expect(page.url()).toBe('https://demoqa.com/');
   });
   test('should not change the URL when clicking on the Bad Request link', async ({ page }) => {
     await page.goto('https://demoqa.com/links');
     await page.click('#bad-request');
     expect(page.url()).toBe('https://demoqa.com/links');
   });
 });
